contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        uint ownerBefore = address(this).balance;
        // send Ether directly into C via its payable fallback
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok);
        require(address(c).balance == amount);
        // the next go() must sweep the stuck funds to the owner
        c.go();
        assert(address(c).balance == 0 && address(this).balance >= ownerBefore + amount);
    }
    receive() external payable {}
}

